<script setup lang="ts">const route=useRoute(),{api}=useShopApi();const isOrder=computed(()=>/^\/profile\/orders\/\d+$/.test(route.path));const{data}=await useAsyncData('route-order-shipment',()=>isOrder.value?api<any>(`/profile/orders/${route.params.id}`):Promise.resolve(null),{watch:[()=>route.fullPath]});const labels:any={preparing:'در حال آماده‌سازی',shipped:'تحویل شرکت حمل',in_transit:'در مسیر',out_for_delivery:'در حال توزیع',delivered:'تحویل‌شده',failed:'ارسال ناموفق',returned:'برگشت‌خورده'}</script>
<template><section v-if="isOrder&&data" class="mx-auto mt-5 max-w-5xl px-4"><div class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-black">پیگیری ارسال</h2><p v-if="data.shipment" class="mt-1 text-sm text-slate-400">{{data.shipment.carrier}} • {{labels[data.shipment.status]}}</p><p v-else class="mt-1 text-sm text-slate-400">اطلاعات ارسال پس از تحویل سفارش به شرکت حمل نمایش داده می‌شود.</p></div><div class="flex gap-2"><NuxtLink :to="`/profile/orders/${data.id}/invoice`" class="rounded-xl border px-4 py-2 text-sm font-bold">مشاهده فاکتور</NuxtLink><a v-if="data.shipment?.tracking_url" :href="data.shipment.tracking_url" target="_blank" class="rounded-xl bg-brand-700 px-4 py-2 text-sm font-bold text-white">رهگیری مرسوله</a></div></div><div v-if="data.shipment?.tracking_code" class="mt-4 rounded-xl bg-brand-50 p-4 text-sm">کد رهگیری: <b dir="ltr">{{data.shipment.tracking_code}}</b></div><div v-if="data.shipment?.events?.length" class="mt-5 space-y-4 border-r-2 border-brand-200 pr-5"><div v-for="e in data.shipment.events" :key="e.id" class="relative text-sm"><span class="absolute -right-[26px] top-1 size-3 rounded-full bg-brand-600 ring-4 ring-white"/><b>{{e.title}}</b><p class="mt-1 text-xs text-slate-400">{{e.location}} • {{new Date(e.occurred_at).toLocaleString('fa-IR')}}</p><p v-if="e.description" class="mt-1 text-slate-500">{{e.description}}</p></div></div></div></section></template>
